/**
 * لوحة المؤسس — كل النداءات عبر edge function `founder-admin`.
 *
 * الدخول ببريد المؤسس نفسه: إن كانت هناك جلسة، تُجرَّب مباشرة فتفتح اللوحة بلا
 * أي خطوة إضافية (البريد المعتمد في `founder_email()` بالقاعدة، لا هنا — فلا
 * يتكرّر في مكانين). وسرّ المؤسس يبقى **مساراً احتياطياً** مطوياً كي لا يُفقد
 * الوصول إن تعطّل شيء في الأول؛ ولا يُضمَّن في الكود أبداً ولا يُحفظ إلا في
 * sessionStorage.
 */
import { useCallback, useEffect, useState, type FormEvent } from "react";
import { Link } from "react-router-dom";
import { Logo } from "@/components/site";
import { Badge, Button, Card, ErrorNote, Field, Input, Skeleton, ThemeToggle, useToast } from "@/components/ui";
import { founderAdmin } from "@/lib/api";
import { useAuth } from "@/lib/auth";
import { K, getItem, removeItem, setItem } from "@/lib/storage";
import { formatDate, formatPrice } from "@/lib/utils";

type Ticket = {
  id: string;
  subject: string | null;
  message: string | null;
  email: string | null;
  restaurant_name: string | null;
  status: string | null;
  admin_reply: string | null;
  created_at: string;
};

type RestaurantRow = { id: string; name: string; slug: string | null; created_at: string };

type Stats = {
  revenue: number;
  activeSubs: number;
  restaurants: number;
  openTickets: number;
};

export default function Founder() {
  const toast = useToast();
  const { user, loading: authLoading, login, logout } = useAuth();
  const [secret, setSecret] = useState(() => getItem(K.FSECRET, true) ?? "");
  const [unlocked, setUnlocked] = useState(false);
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  /** فحص الجلسة الحالية جارٍ — يمنع وميض شاشة الدخول أمام المؤسس المسجَّل. */
  const [probing, setProbing] = useState(true);
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [showSecret, setShowSecret] = useState(false);
  const [stats, setStats] = useState<Stats | null>(null);
  const [tickets, setTickets] = useState<Ticket[] | null>(null);
  const [restaurants, setRestaurants] = useState<RestaurantRow[] | null>(null);

  useEffect(() => {
    document.title = "لوحة المؤسس — كلاود منيو";
  }, []);

  const loadAll = useCallback(async () => {
    const [revenue, subs, rests, ticketRows] = await Promise.all([
      founderAdmin<{ amount: number | null }[]>("revenue_log?select=amount"),
      founderAdmin<{ id: string }[]>("subscriptions?active=eq.true&select=id"),
      founderAdmin<RestaurantRow[]>(
        "restaurants?select=id,name,slug,created_at&order=created_at.desc&limit=30"
      ),
      founderAdmin<Ticket[]>("support_tickets?select=*&order=created_at.desc&limit=30"),
    ]);
    setStats({
      revenue: revenue.reduce((s, r) => s + (r.amount ?? 0), 0),
      activeSubs: subs.length,
      restaurants: rests.length,
      openTickets: ticketRows.filter((t) => t.status === "open").length,
    });
    setRestaurants(rests);
    setTickets(ticketRows);
  }, []);

  /**
   * محاولة صامتة بما هو موجود (جلسة أو سرّ محفوظ).
   *
   * لا نسأل الواجهة «هل هذا بريد المؤسس؟» — الدالة وحدها تعرف الجواب، ونسخُ
   * البريد إلى العميل يكرّر مصدر الحقيقة. نجرّب النداء: نجح ⇒ افتح، فشل ⇒ اعرض
   * الدخول.
   */
  useEffect(() => {
    if (authLoading) return;
    let alive = true;
    if (!user && !getItem(K.FSECRET, true)) {
      setProbing(false);
      return;
    }
    loadAll()
      .then(() => alive && setUnlocked(true))
      .catch(() => {})
      .finally(() => alive && setProbing(false));
    return () => {
      alive = false;
    };
  }, [authLoading, user, loadAll]);

  /** دخول ببريد المؤسس — الحساب نفسه الذي يملك المنصة. */
  async function signIn(e: FormEvent) {
    e.preventDefault();
    setError("");
    setBusy(true);
    try {
      await login(email.trim(), password);
      await loadAll();
      setUnlocked(true);
    } catch {
      setError("البريد أو كلمة المرور غير صحيحة، أو هذا الحساب ليس حساب المؤسس.");
    } finally {
      setBusy(false);
    }
  }

  /** المسار الاحتياطي بالسرّ — يبقى حتى يتأكّد المؤسس أن دخول البريد يعمل. */
  async function unlock(e: FormEvent) {
    e.preventDefault();
    setError("");
    setBusy(true);
    setItem(K.FSECRET, secret.trim(), true);
    try {
      await loadAll();
      setUnlocked(true);
    } catch {
      removeItem(K.FSECRET, true);
      setError("السر غير صحيح أو الخدمة غير متاحة.");
    } finally {
      setBusy(false);
    }
  }

  /** ردّ المؤسس — يظهر للتاجر في صندوق الدعم داخل إعداداته. */
  async function replyTicket(t: Ticket) {
    const reply = window.prompt(`الرد على «${t.subject ?? "التذكرة"}»:`, t.admin_reply ?? "")?.trim();
    if (reply === undefined || reply === "") return;
    try {
      await founderAdmin(`support_tickets?id=eq.${t.id}`, {
        method: "PATCH",
        body: { admin_reply: reply, admin_read: true },
      });
      setTickets((rows) =>
        rows?.map((x) => (x.id === t.id ? { ...x, admin_reply: reply } : x)) ?? null
      );
      toast("أُرسل الرد للتاجر ✓");
    } catch {
      toast("تعذّر إرسال الرد.", "err");
    }
  }

  async function setTicketStatus(t: Ticket, status: string) {
    try {
      await founderAdmin(`support_tickets?id=eq.${t.id}`, {
        method: "PATCH",
        body: { status },
      });
      setTickets((rows) => rows?.map((x) => (x.id === t.id ? { ...x, status } : x)) ?? null);
      toast("تم تحديث التذكرة.");
    } catch {
      toast("تعذّر التحديث.", "err");
    }
  }

  // قاعدة حالات التحميل: لا نعرض جدار الدخول قبل أن تُحسم الجلسة والمحاولة.
  if (!unlocked && (authLoading || probing)) {
    return (
      <div className="flex min-h-dvh items-center justify-center px-5">
        <Skeleton className="h-40 w-full max-w-sm" />
      </div>
    );
  }

  if (!unlocked) {
    return (
      <div className="glow-bg flex min-h-dvh flex-col">
        <header className="flex items-center justify-between px-5 py-4">
          <Link to="/"><Logo /></Link>
          <ThemeToggle />
        </header>
        <main className="flex flex-1 items-center justify-center px-5 pb-16">
          <Card className="anim-fade-up w-full max-w-sm p-7 text-center">
            <span className="text-4xl">🛡️</span>
            <h1 className="mt-3 font-display text-xl font-black text-ink">لوحة المؤسس</h1>
            <p className="mt-1 text-sm text-dim">
              {user
                ? "هذا الحساب ليس حساب المؤسس — سجّل الدخول ببريد المؤسس."
                : "سجّل الدخول ببريد المؤسس."}
            </p>

            <form onSubmit={signIn} className="mt-5 flex flex-col gap-3 text-right">
              <Field label="البريد">
                <Input
                  type="email"
                  dir="ltr"
                  autoComplete="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="you@example.com"
                  required
                />
              </Field>
              <Field label="كلمة المرور">
                <Input
                  type="password"
                  dir="ltr"
                  autoComplete="current-password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder="••••••••"
                  required
                />
              </Field>
              {error && <ErrorNote>{error}</ErrorNote>}
              <Button type="submit" disabled={busy} className="w-full">
                {busy ? "جارٍ التحقق…" : "دخول"}
              </Button>
            </form>

            {user && (
              <button
                onClick={() => {
                  logout();
                  setError("");
                }}
                className="mt-3 text-xs font-bold text-dim hover:text-ink"
              >
                تسجيل الخروج من «{user.email}»
              </button>
            )}

            {/* المسار الاحتياطي — مطويّ كي لا يكون هو الطريق المعتاد. */}
            <details className="mt-5 text-right" open={showSecret}>
              <summary
                onClick={() => setShowSecret((v) => !v)}
                className="cursor-pointer text-center text-xs font-bold text-faint hover:text-dim"
              >
                الدخول بسر المؤسس (احتياطي)
              </summary>
              <form onSubmit={unlock} className="mt-3 flex flex-col gap-3">
                <Field label="السر">
                  <Input
                    type="password"
                    dir="ltr"
                    value={secret}
                    onChange={(e) => setSecret(e.target.value)}
                    placeholder="••••••••••"
                    required
                  />
                </Field>
                <Button type="submit" variant="ghost" disabled={busy} className="w-full">
                  {busy ? "جارٍ التحقق…" : "دخول بالسر"}
                </Button>
              </form>
            </details>
          </Card>
        </main>
      </div>
    );
  }

  const statCards = [
    { label: "إجمالي الإيراد", value: `${formatPrice(stats?.revenue ?? 0)} ر.س`, icon: "💰" },
    { label: "اشتراكات نشطة", value: stats?.activeSubs ?? 0, icon: "📦" },
    { label: "مطاعم (آخر ٣٠)", value: stats?.restaurants ?? 0, icon: "🍽️" },
    { label: "تذاكر مفتوحة", value: stats?.openTickets ?? 0, icon: "🎫" },
  ];

  return (
    <div className="min-h-dvh">
      <header className="sticky top-0 z-30 border-b border-line bg-page/85 backdrop-blur-lg">
        <div className="mx-auto flex h-16 max-w-5xl items-center justify-between px-5">
          <Link to="/"><Logo /></Link>
          <div className="flex items-center gap-2">
            <Badge>🛡️ المؤسس</Badge>
            <ThemeToggle />
          </div>
        </div>
      </header>

      <main className="mx-auto max-w-5xl px-5 py-8">
        <h1 className="font-display text-2xl font-black text-ink">نظرة عامة على المنصة</h1>

        <div className="mt-6 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
          {statCards.map((s) => (
            <Card key={s.label} className="flex items-center gap-3">
              <span className="flex h-11 w-11 items-center justify-center rounded-xl bg-gold/12 text-xl">
                {s.icon}
              </span>
              <div>
                <p className="text-xs text-dim">{s.label}</p>
                <p className="font-display text-xl font-black text-ink">{s.value}</p>
              </div>
            </Card>
          ))}
        </div>

        <section className="mt-10">
          <h2 className="mb-4 font-display text-lg font-extrabold text-ink">🎫 تذاكر الدعم</h2>
          {tickets === null ? (
            <Skeleton className="h-40" />
          ) : tickets.length === 0 ? (
            <Card className="text-center text-sm text-dim">لا توجد تذاكر.</Card>
          ) : (
            <div className="flex flex-col gap-3">
              {tickets.map((t) => (
                <Card key={t.id} className="flex flex-wrap items-center justify-between gap-3">
                  <div className="min-w-0">
                    <p className="font-bold text-ink">{t.subject ?? "بلا موضوع"}</p>
                    {t.message && <p className="mt-0.5 line-clamp-2 text-sm text-dim">{t.message}</p>}
                    <p className="mt-1 text-xs text-faint">
                      {t.restaurant_name && <span>{t.restaurant_name} · </span>}
                      {t.email && <span dir="ltr">{t.email} · </span>}
                      {formatDate(t.created_at)}
                    </p>
                    {t.admin_reply && (
                      <p className="mt-1.5 rounded-lg border border-gold/30 bg-gold/[.06] px-2.5 py-1.5 text-xs text-ink">
                        ردّك: {t.admin_reply}
                      </p>
                    )}
                  </div>
                  <div className="flex items-center gap-2">
                    <Button
                      variant="outline"
                      className="px-3 py-1.5 text-xs"
                      onClick={() => replyTicket(t)}
                    >
                      {t.admin_reply ? "تعديل الرد" : "ردّ"}
                    </Button>
                    <Badge variant={t.status === "open" ? "red" : "green"}>
                      {t.status === "open" ? "مفتوحة" : "مغلقة"}
                    </Badge>
                    <Button
                      variant="outline"
                      className="px-3 py-1.5 text-xs"
                      onClick={() => setTicketStatus(t, t.status === "open" ? "closed" : "open")}
                    >
                      {t.status === "open" ? "إغلاق" : "إعادة فتح"}
                    </Button>
                  </div>
                </Card>
              ))}
            </div>
          )}
        </section>

        <section className="mt-10">
          <h2 className="mb-4 font-display text-lg font-extrabold text-ink">🍽️ أحدث المطاعم</h2>
          {restaurants === null ? (
            <Skeleton className="h-40" />
          ) : (
            <div className="grid gap-3 sm:grid-cols-2">
              {restaurants.map((r) => (
                <Card key={r.id} className="flex items-center justify-between gap-3">
                  <div>
                    <p className="font-bold text-ink">{r.name}</p>
                    <p className="text-xs text-faint">{formatDate(r.created_at)}</p>
                  </div>
                  {r.slug && (
                    <a href={`/${r.slug}`} target="_blank" rel="noopener noreferrer" className="text-sm font-bold text-gold hover:underline">
                      عرض ↗
                    </a>
                  )}
                </Card>
              ))}
            </div>
          )}
        </section>
      </main>
    </div>
  );
}
